source.exploreUrl:
@js:
var conf = ensureConfig.call(this);
var currentSource = conf.source || '';
var currentGender = conf.gender || 'boy';

var srcList = getSourceList.call(this);
var srcMeta = {};
for (var i = 0; i < srcList.length; i++) {
    srcMeta[srcList[i].name] = srcList[i];
}

var currentMode = conf.mode || 'novel';
var firstSource = String(currentSource || '').split(',')[0].trim();
if (firstSource && srcMeta[firstSource] && srcMeta[firstSource].tab) {
    currentMode = srcMeta[firstSource].tab;
}

var MODE_LABELS = {
    novel: '📖小说',
    audio: '🎧听书',
    comic: '🌈漫画',
    video: '▶️短剧',
    download: '⬇️下载'
};
var LABEL_TO_MODE = {
    '📖小说': 'novel',
    '🎧听书': 'audio',
    '🌈漫画': 'comic',
    '▶️短剧': 'video',
    '⬇️下载': 'download'
};

var srcOptions = [{ label: '☁️聚合搜索', value: '' }];
for (var i = 0; i < srcList.length; i++) {
    var it = srcList[i];
    if (it.tab && it.tab != currentMode) continue;
    srcOptions.push({ label: it.name, value: it.name });
}

var defaultLabel = '☁️聚合搜索';
for (var k = 0; k < srcOptions.length; k++) {
    if (srcOptions[k].value == firstSource) { defaultLabel = srcOptions[k].label; break; }
}
var srcMapStr = JSON.stringify(srcOptions).replace(/\\/g,'\\\\').replace(/"/g,'\\"');

var firstModeSource = '';
for (var i = 0; i < srcList.length; i++) {
    if (srcList[i].tab == currentMode && srcList[i].name) { firstModeSource = srcList[i].name; break; }
}
var useSource = firstSource || firstModeSource;

var controls = [];
controls.push({ title: '☃关键词💭：书名/作者', type: 'text', style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.6 } });
controls.push({ title: '🔍搜索', type: 'button', action: "java.searchBook(infoMap['☃关键词💭：书名/作者'] || '')", style: { layout_flexGrow: 1, layout_flexBasisPercent: -1, layout_alignSelf: 'baseline' } });
controls.push({ title: '🔄刷新', type: 'button', action: 'java.refreshExplore()', style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.4, layout_alignSelf: 'baseline' } });
controls.push({ title: '⚙登录', type: 'button', action: "java.open('login','http',null)", style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.4, layout_alignSelf: 'baseline' } });

controls.push({
    title: '性别',
    type: 'select',
    chars: ['♂️男频', '♀️女频'],
    default: currentGender == 'girl' ? '♀️女频' : '♂️男频',
    action: "(function(){var raw=infoMap['性别']||'';var v=(raw.indexOf('女')>=0)?'girl':'boy';setConfig.call(this,{gender:v});java.refreshExplore();})()",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.4 }
});

controls.push({
    title: '模式',
    type: 'select',
    chars: ['📖小说', '🎧听书', '🌈漫画', '▶️短剧', '⬇️下载'],
    default: MODE_LABELS[currentMode] || '📖小说',
    action: "(function(){var raw=infoMap['模式']||'';var map=JSON.parse('" + JSON.stringify(LABEL_TO_MODE).replace(/\\/g,'\\\\').replace(/"/g,'\\"') + "');var v=map[raw]||'novel';setConfig.call(this,{mode:v,source:''});java.refreshExplore();})()",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.4 }
});

controls.push({
    title: '源站',
    type: 'select',
    chars: srcOptions.map(function(x){return x.label;}),
    default: defaultLabel,
    action: "(function(){var raw=infoMap['源站']||'';var opts=JSON.parse('" + srcMapStr + "');var map={};opts.forEach(function(i){map[i.label]=i.value;});setConfig.call(this,{source:map[raw]||''});java.refreshExplore();})()",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
});

var currentJjTab = getConfig.call(this).jj_tab || '多元';
if (String(useSource).indexOf('晋江') >= 0) {
    var jjTabs = ["🏷 言情", "🏷 纯爱", "🏷 百合", "🏷 无Cp", "🏷 多元"];
    var jjTagMap = {"🏷 言情":"言情","🏷 纯爱":"纯爱","🏷 百合":"百合","🏷 无Cp":"无Cp","🏷 多元":"多元"};
    var jjTagMapStr = JSON.stringify(jjTagMap).replace(/\\/g,'\\\\').replace(/"/g,'\\"');

    controls.push({
        title: '频道',
        type: 'select',
        chars: jjTabs,
        default: "🏷 " + currentJjTab,
        action: "(function(){var raw=infoMap['频道']||'';var tagMap=JSON.parse('" + jjTagMapStr + "');var tagName=tagMap[raw]||'多元';setConfig.call(this,{jj_tab:tagName});java.refreshExplore();})()",
        style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
    });
}

var sort = controls.slice();

/* v41.24：发现页书架（聚合/番茄显示番茄，晋江显示晋江；其他源不显示） */
var shelfEntries = [];
var shelfFirstSource = String(firstSource || '').trim();
var showFanqieShelf = shelfFirstSource == '' || shelfFirstSource.indexOf('番茄') >= 0;
var showJjShelf = shelfFirstSource.indexOf('晋江') >= 0;

function shelfUrl(sourceName, loginValue, groupValue) {
    return getHost.call(this) + '/api/bookshelf,' + JSON.stringify({
        method: 'POST',
        body: JSON.stringify({
            source: sourceName,
            logins: String(loginValue || ''),
            group: String(groupValue || '')
        }),
        headers: buildHeaders.call(this)
    });
}

function makeShelfBookList(sourceName, loginValue) {
    try {
        var shelfRes = postJson.call(this, '/api/bookshelf', {
            source: sourceName,
            logins: String(loginValue || ''),
            group: ''
        });
        if (shelfRes && shelfRes.code == 0 && Array.isArray(shelfRes.data)) {
            return shelfRes.data;
        }
    } catch (e) {}
    return [];
}

function shelfGroups(books) {
    var seen = {};
    var groups = [];
    for (var i = 0; i < books.length; i++) {
        var g = String((books[i] && (books[i].group_name || books[i].group_id)) || '').trim();
        if (!g || seen[g]) continue;
        seen[g] = true;
        groups.push(g);
    }
    return groups;
}

function pushShelfDivider() {
    shelfEntries.push({
        title: '────────',
        url: '',
        style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
    });
}

var fqSession = getSessionId.call(this) || getSessionIdFromCookie.call(this);
if (showFanqieShelf && fqSession) {
    var fqBooks = makeShelfBookList.call(this, '番茄', fqSession);
    var fqGroups = shelfGroups(fqBooks);
    var fqName = '';
    try {
