let localVersion = '1.20261105.1';  //本地版本号

function getHosts() {
    return [
    'https://tingx.abrdns.com',
    'http://154.12.85.126:5000'
    ];
}

function getHost() {
    let { source } = this;
    let c = getConfig.call(this);
    if (c.host) return String(c.host).replace(/\/+$/, '');
    let base = '';
    try { base = "https://tingx.abrdns.com"; } catch (e) {}
    if (!base && typeof baseUrl !== 'undefined' && baseUrl) base = String(baseUrl);
    if (!base) base = getHosts()[0];
    return base.replace(/\/+$/, '');
}

function getConfig() {
    let { source } = this;
    try {
        let configStr = source.getVariable();
        if (!configStr || configStr.trim() == "") return {};
        let config = JSON.parse(configStr);
        if (Array.isArray(config)) return config[0] || {};
        if (config && typeof config == 'object') return config;
        return {};
    } catch (e) { return {}; }
}

function setConfig(obj) {
    let { source } = this;
    try {
        let config = getConfig.call(this);
        for (let k in obj) { if (obj.hasOwnProperty(k)) config[k] = obj[k]; }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) { return false; }
}

function ensureConfig() {
    let c = getConfig.call(this);
    let changed = false;
    if (!c.gender) { c.gender = 'boy'; changed = true; }
    if (c.source == undefined) { c.source = ''; changed = true; }
    if (!c.sources) { c.sources = { novel: [], audio: [], comic: [], video: [], download: [] }; changed = true; }
    if (changed) setConfig.call(this, c);
    return c;
}

function deviceType() {
    let { java } = this;
    try {
        var id = java.deviceID();
        if (id && id !== '') {
            return true;
        }
    } catch (e) {}

    try {
        var id = java.androidId();
        if (id && id !== '') {
            return false;
        }
    } catch (e) {}

    return false;
}

function getDeviceId() {
    let { java } = this;
    let dev = '';
    try { let id1 = java.deviceID(); if (id1 && String(id1) !== '') dev = String(id1); } catch (e) {}
    if (!dev) { try { let id2 = java.androidId(); if (id2 && String(id2) !== '') dev = String(id2); } catch (e) {} }
    return dev;
}

function checkMsg(res) {
    let { java } = this;
    try {
        let obj = JSON.parse(res);
        if (obj.code !== 0) {
            java.toast(obj.message);
        }
    } catch (e) {}
    return res;
}

function getToken() {
    let { source } = this;
    let b64 = '';
    try { b64 = String(source.getLoginHeader() || '').trim(); } catch (e) {}
    return { b64: b64 };
}

function buildHeaders() {
    let { java } = this;
    let t = getToken.call(this);
    let dev = getDeviceId.call(this);
    let ts = String(Math.floor(Date.now() / 1000));

    let plain = '';
    if (t.b64) {
        try { plain = java.base64Decode(t.b64); } catch (e) { plain = ''; }
    }

    return {
        'User-Agent': java.getWebViewUA(),
        'x-novel-token': t.b64,
        'x-novel-deviceid': dev,
        'x-novel-timestamap': ts,
        'x-novel-public': java.md5Encode(plain + dev + ts).toLowerCase(),
        'x-novel-version': '2'
    };
}

function postJson(path, obj) {
    let { java } = this;
    let headers = buildHeaders.call(this);
    headers['Content-Type'] = 'application/json';
    let opt = { method: 'POST', body: JSON.stringify(obj || {}), headers: headers };
    let res = java.ajax(getHost.call(this) + path + ',' + JSON.stringify(opt));
    res = decryptIfEncrypted.call(this, res);
    try { return JSON.parse(res); } catch (e) { return { code: -1, message: '解析失败', raw: res }; }
}

function getSourceList() {
    let list = [];
    try {
        let arr = postJson.call(this, '/api/source', {});
        if (Array.isArray(arr)) {
            arr.forEach(function (it) { if (it && it.enabled && it.name) list.push(it); });
            list.sort(function (a, b) { return (a.sort || 0) - (b.sort || 0); });
        }
    } catch (e) {}
    return list;
}

function getCmtBrowserOptions() {
    return {
        expandedCornersRadius: 20,
        dismissOnTouchOutside: true,
        isDraggable: true,
        shouldDimBackground: true,
        backgroundDimAmount: 0.5,
        hardwareAccelerated: true,
        isNestedScrollingEnabled: true,
        isGestureInsetBottomIgnored: true,
        setFitToContents: false,
        heightPercentage: 0.75,
        isHideable: true
    };
}

