    let { java } = this;
    let url = getHost.call(this) + '/comment'
            + '?tab=paras&book_id=' + bid
            + '&item_id=' + cid
            + '&para=' + para
            + '&source=' + (sourceName || '');
    try {
        java.showBrowser(url, null, 'window.java=java;', JSON.stringify(getCmtBrowserOptions.call(this)));
    } catch (e) {
        try { java.startBrowser(url, '段评'); } catch (e2) {
            java.toast('打开段评失败：' + e2);
        }
    }
}

function getSessionId() {
    let config = getConfig.call(this);
    return String(config.fanqie_sessionid || '');
}

