    const { cookie } = this;
    try {
        let cookieHeader = String(cookie.getCookie('fanqienovel.com'));
        let sessionId = cookieHeader.match(/sessionid=([^;]+)/)?.[1] || null;
        if (sessionId) return sessionId;
    } catch (e) {}
    return "";
}

function getJjToken() {
    let config = getConfig.call(this);
    return String(config.jj_token || '');
}

function buildJjHeaders() {
    let { java } = this;
    return {
        "source": "android",
        "versiontype": "reading",
        "versioncode": "467",
        "version-code": "467",
        "User-Agent": java.getWebViewUA()
    };
}

function jjEncode(data) {
    let { java } = this;
    return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", "KW8Dvm2N", "1ae2c94b").encryptBase64(data);
}

function isShelfSyncEnabled() {
    try {
        return String(getConfig.call(this).shelf_sync || 'off') == 'on';
    } catch (e) {
        return false;
    }
}

