    let { java, book } = this;
    try {
        if (!book || !book.tocUrl) return;
        let raw = String(book.tocUrl || '').replace(/\\/g, '').replace(/^data:catalogUrl;base64,/, '');
        let idx = raw.indexOf(',');
        if (idx >= 0) raw = raw.substring(0, idx);
        raw = raw.replace(/[^A-Za-z0-9+/=]/g, '');
        let catalog = JSON.parse(String(java.base64Decode(raw) || '').replace(/\\/g, ''));
        let sourceName = String(catalog.source || '');
        let bookId = String(catalog.book_id || catalog.bookid || '');
        if (!bookId) return;

        let apiSource = '';
        let logins = '';
        if (sourceName.indexOf('番茄') >= 0) {
            apiSource = '番茄';
            logins = getSessionId.call(this) || getSessionIdFromCookie.call(this);
        } else if (sourceName.indexOf('晋江') >= 0) {
            apiSource = '晋江';
            logins = getJjToken.call(this);
        }
        if (!apiSource || !logins) {
            java.toast('书架同步：请先登录' + apiSource);
            return;
        }

        let res = postJson.call(this, '/api/bookshelf/sync', {
            source: apiSource,
            logins: String(logins),
            book_id: bookId,
            action: isAdd ? 'add' : 'del',
            group: ''
