            for (let i = 0; i < data.length; i += 16) {
                let block = new Array(16).fill(0);
                for (let j = 0; j < 16 && i + j < data.length; j++) block[j] = data[i+j];
                for (let j = 0; j < 16; j++) y[j] ^= block[j];
                y = gfMul(y, H);
            }
            let lenBlock = new Array(16).fill(0);
            writeBitsBE(lenBlock, 0, aadBits);
            writeBitsBE(lenBlock, 8, ctBits);
            for (let j = 0; j < 16; j++) y[j] ^= lenBlock[j];
            y = gfMul(y, H);
            return y;
        }
        function inc32(block) {
            for (let i = 15; i >= 12; i--) {
                block[i] = (block[i] + 1) & 0xFF;
                if (block[i] !== 0) break;
            }
        }
        function gcmDecrypt(key, iv, ct, tag) {
            let rk = expandKey(key);
            let H = encryptBlock(rk, new Array(16).fill(0));
            let J0;
            if (iv.length == 12) J0 = iv.concat([0, 0, 0, 1]);
            else J0 = ghash(H, iv, 0, iv.length * 8);
            let S = ghash(H, ct, 0, ct.length * 8);
            let ej0 = encryptBlock(rk, J0);
            let calcTag = new Array(16);
            for (let i = 0; i < 16; i++) calcTag[i] = S[i] ^ ej0[i];
            for (let i = 0; i < 16; i++) {
                if (calcTag[i] !== tag[i]) return null;
            }
            let out = [];
            let ctr = J0.slice();
            for (let i = 0; i < ct.length; i += 16) {
                inc32(ctr);
                let ks = encryptBlock(rk, ctr);
                for (let j = 0; j < 16 && i + j < ct.length; j++) {
                    out.push(ct[i+j] ^ ks[j]);
                }
            }
            return out;
        }

        let key = [];
        let keyStr = "Lk4#Fj9&Gh1*Ds6^Qw3!Er8@Ty5%Ui0o";
        for (let i = 0; i < keyStr.length; i++) key.push(keyStr.charCodeAt(i) & 0xFF);

        let iv = b64dec(obj.iv);
        let tag = b64dec(obj.tag);
        let ct = b64dec(obj.data);

        let plain = gcmDecrypt(key, iv, ct, tag);
        if (!plain) return payload;
        return utf8dec(plain);
    } catch (e) {
        return payload;
    }
}

function getJjShelfClass() {
