        }

        var url = "https://app.jjwxc.org/app.jjwxc/android/reading/FavoriteClass/favoriteClass";
        var body = encode.call(this, JSON.stringify({
            "versionCode": "444",
            "token": token
        }));

        var headers = {
            "versioncode": "444",
            "versiontype": "reading",
            "User-Agent": java.getWebViewUA()
        };

        var res = java.post(url, body, headers).body();
        var data = JSON.parse(res);

        if (!data || !data.data || !data.data.length) {
            java.log("获取分类失败: " + res);
            java.toast("获取分类失败，请检查登录状态");
            return;
        }

        var excludeIds = { "-1": true, "-2": true, "-3": true };
        var classList = [];
        for (var i = 0; i < data.data.length; i++) {
