            var cid = String(item.classid);
            if (excludeIds[cid]) continue;
            classList.push({
                classId: cid,
                className: String(item.classname)
            });
        }

        if (classList.length == 0) {
            java.toast("暂无可用分类");
            return;
        }

        var config = getConfig.call(this);
        var savedId = String(config.type_id || "");

        var cardsHtml = "";
        for (var j = 0; j < classList.length; j++) {
            var c = classList[j];
            var selected = (String(c.classId) == savedId) ? " selected" : "";
            cardsHtml +=
                '<div class="class-card' + selected + '" data-id="' + c.classId + '" onclick="pick(this)">' +
                    '<div class="class-name">' + c.className + '</div>' +
                    '<div class="class-id">ID: ' + c.classId + '</div>' +
                '</div>';
        }

        var html = `<!DOCTYPE html>
