    var body = choice.body();
    var m = body.match(/<div id="result-output"[^>]*>([^<]*)<\/div>/);
    var rawOut = (m && m[1]) ? m[1].trim() : '';
    rawOut = rawOut.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'");

    var newSources = { novel: [], audio: [], comic: [], video: [], download: [] };
    var newAllTabs = [];
    try {
        var parts = rawOut.split('|||');
        var allArr = JSON.parse(parts[0] || '[]');
        var srcObj = JSON.parse(parts[1] || '{}');
        if (Array.isArray(allArr)) newAllTabs = allArr;
        if (srcObj && typeof srcObj == 'object') {
            TABS.forEach(function (t) { if (Array.isArray(srcObj[t])) newSources[t] = srcObj[t]; });
        }
    } catch (e) {}

    TABS.forEach(function (t) {
        if (newSources[t].length > 0) {
            newAllTabs = newAllTabs.filter(function (x) { return x !== t; });
        }
    });

    var merged = [];
    TABS.forEach(function (t) {
        newSources[t].forEach(function (n) { if (merged.indexOf(n) == -1) merged.push(n); });
    });

    setConfig.call(this, { sources: newSources, allTabs: newAllTabs, source: merged.join(',') });
    var cnt = merged.length;
    var allCnt = newAllTabs.length;
    java.toast(cnt > 0 ? ('源站已保存（共 ' + cnt + ' 个）') : (allCnt > 0 ? '已保存（全部源站）' : '已保存（未选择具体源站）'));
}

function parseVer(v) {
    return String(v || '').split('.').map(function (x) { return parseInt(x, 10) || 0; });
}

function cmpVer(a, b) {
    let pa = parseVer(a), pb = parseVer(b);
    let len = Math.max(pa.length, pb.length);
    for (let i = 0; i < len; i++) {
        let x = pa[i] || 0, y = pb[i] || 0;
        if (x > y) return 1;
        if (x < y) return -1;
    }
    return 0;
}

function shouldBlockByVersion(serverVerObj) {
    if (!serverVerObj || !serverVerObj.version) return false;
    let sv = String(serverVerObj.version);
    let lv = String(localVersion || '');
    if (cmpVer(sv, lv) <= 0) return false;

    let isForce = (serverVerObj.force == true || String(serverVerObj.force) == 'true');
    let tipMsg = serverVerObj.msg || '';   // ← 用 version.msg

    if (isForce) {
        try { java.toast('\n服务端要求强制更新 ' + sv + (tipMsg ? '\n' + tipMsg : '')); } catch (e) {}
        try { checkVersion.call(this); } catch (e) {}
    } else {
        try { java.toast('有新版本 ' + sv + (tipMsg ? '\n' + tipMsg : '') + '\n可在登录页「🔄更新检测」查看'); } catch (e) {}
    }

    return false;
}

