        '.hero{display:flex;align-items:center;gap:14px;padding:17px 18px;margin-bottom:12px}' +
        '.hero-icon{flex:0 0 auto;width:46px;height:46px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:20px;' +
        'background:linear-gradient(135deg,var(--primary),var(--primary-dark));color:#fff}' +
        '.hero h1{margin:0;font-size:19px;line-height:1.25}' +
        '.hero p{margin:5px 0 0;font-size:12px;line-height:1.55;color:var(--muted)}' +
