        '</div></div>' +
        '<div class="row"><div><div class="label">源阅适配</div><div class="desc">IOS源阅适配，其他IOS应用段评异常也可尝试开启</div></div>' +
        '<label class="switch"><input type="checkbox" id="sySwitch" ' + (curSy == 'on' ? 'checked' : '') + '><span class="switch-slider"></span></label></div>' +
        '</section>' +

        // 同步
        '<section class="card glass">' +
        '<div class="group-title">同步</div>' +
        '<div class="row"><div><div class="label">进度同步</div><div class="desc">翻章时上报晋江 / 番茄系列阅读进度</div></div>' +
        '<label class="switch"><input type="checkbox" id="progressSwitch" ' + (curProgress == 'on' ? 'checked' : '') + '><span class="switch-slider"></span></label></div>' +
        '<div class="row"><div><div class="label">书架同步</div><div class="desc">加入/移除书架时同步到晋江 / 番茄系列</div></div>' +
        '<label class="switch"><input type="checkbox" id="shelfSwitch" ' + (curShelf == 'on' ? 'checked' : '') + '><span class="switch-slider"></span></label></div>' +
        '</section>' +

        '<div class="tip glass">当前：段评 <b id="curReview">' + (curReview == 'on' ? '开启' : '关闭') + '</b> · 图标 <b id="curStyle">' + curStyle + '</b> · 源阅适配 <b id="curSy">' + (curSy == 'on' ? '开启' : '关闭') + '</b>' +
        ' · 进度同步 <b id="curProgress">' + (curProgress == 'on' ? '开启' : '关闭') + '</b> · 书架同步 <b id="curShelf">' + (curShelf == 'on' ? '开启' : '关闭') + '</b></div>' +
        '</div>' +
        '<div id="result-output" style="display:none;">' + curReview + '|' + curStyle + '|' + curSy + '|' + curProgress + '|' + curShelf + '</div>' +
        '<script>' +
        'var out=document.getElementById("result-output");' +
        'function sync(){var r=document.getElementById("reviewSwitch").checked?"on":"off";' +
        'var s=document.querySelector("#styleSeg button.on").getAttribute("data-val");' +
        'var y=document.getElementById("sySwitch").checked?"on":"off";' +
        'var p=document.getElementById("progressSwitch").checked?"on":"off";' +
        'var b=document.getElementById("shelfSwitch").checked?"on":"off";' +
        'out.textContent=r+"|"+s+"|"+y+"|"+p+"|"+b;' +
        'document.getElementById("curReview").textContent=r=="on"?"开启":"关闭";' +
        'document.getElementById("curStyle").textContent=s;' +
        'document.getElementById("curSy").textContent=y=="on"?"开启":"关闭";' +
        'document.getElementById("curProgress").textContent=p=="on"?"开启":"关闭";' +
        'document.getElementById("curShelf").textContent=b=="on"?"开启":"关闭";}' +
        '["reviewSwitch","sySwitch","progressSwitch","shelfSwitch"].forEach(function(id){document.getElementById(id).addEventListener("change",sync);});' +
        'document.querySelectorAll("#styleSeg button").forEach(function(btn){btn.addEventListener("click",function(){' +
        'document.querySelectorAll("#styleSeg button").forEach(function(x){x.classList.remove("on");});' +
        'btn.classList.add("on");sync();});});' +
        'sync();' +
        '</script></body></html>';

    var choice = java.startBrowserAwait('data:text/html;base64,' + java.base64Encode(html), '书源设置', false);
    if (!choice || !choice.body()) { java.toast('已取消书源设置'); return; }

    var body = choice.body();
    var m = body.match(/<div id="result-output"[^>]*>([^<]*)<\/div>/);
    var raw = (m && m[1]) ? m[1].trim() : '';
    var parts = raw.split('|');
    var review = parts[0] == 'on' ? 'on' : 'off';
    var style = parts[1] == 'text' ? 'text' : 'TEXT';
    var sy = parts[2] == 'on' ? 'on' : 'off';
    var progress = parts[3] == 'on' ? 'on' : 'off';
    var shelf = parts[4] == 'on' ? 'on' : 'off';

    setConfig.call(this, {
        para_review: review,
        para_style: style,
        para_sy: sy,
        progress_sync: progress,
        shelf_sync: shelf
    });
    java.toast('已保存：段评' + (review == 'on' ? '开启' : '关闭') +
        ' · 进度同步' + (progress == 'on' ? '开启' : '关闭') +
        ' · 书架同步' + (shelf == 'on' ? '开启' : '关闭'));
}

function encode(data) {
    let { java } = this;
    return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data);
}

function decode(data) {
    let { java } = this;
    try {
        var encryptedBytes = java.base64DecodeToByteArray(data);
        var key = "F#kL9$mQpR2&sVzX";
        var iv = "7HnT3!cW8@xM0yBv";
        var crypto = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
        return crypto.decryptStr(encryptedBytes);
    } catch (e) {
        return data;
    }
}

