source.loginUrl:
function login(flag) {
    let email = '', pwd = '';
    try {
        if (flag == true) {
            email = result.get('邮箱') || '';
            pwd = result.get('密码') || '';
        } else {
            let info = source.getLoginInfoMap() || {};
            email = info.get('邮箱') || '';
            pwd = info.get('密码') || '';
        }
    } catch (e) {}

    email = String(email || '').trim();
    pwd = String(pwd || '').trim();
    if (!email || !pwd) return java.toast('请先填写邮箱和密码');

    java.toast('正在登录…');
    try {
        let opt = { method: 'POST', body: JSON.stringify({ email: email, password: pwd }) };
        let res = java.ajax(getHost.call(this) + '/api/login,' + JSON.stringify(opt));
        let obj = null;
        try { obj = JSON.parse(res); } catch (e) { obj = null; }

        if (!obj || obj.code !== 0 || !obj.data || !obj.data.token) {
            let msg = (obj && obj.message) || '未知错误';
            return java.toast('\n❌ 登录失败：' + msg);
        }

        let d = obj.data;
        let u = d.user || {};
        let g = d.group || {};
        let m = d.membership || {};
        let benefits = d.benefits || m.benefits || g.benefits || '';

        source.putLoginHeader(d.token);

        let name = u.nickname || u.email || email;
        let level = g.level || m.level || 1;
        let groupName = g.name || m.group_name || '普通用户';
        let isMember = !!(u.is_member || m.is_member);
        let expires = m.expires_at || d.member_expires_at || '';
        let masked = d.api_token_masked || '';
        let rateWin = g.rate_limit_window || '';
        let rateMax = g.rate_limit_max || '';
        let devLimit = g.device_limit || '';
        let resetLimit = g.token_reset_limit || '';
        let resetDays = g.token_reset_window_days || '';

        let lines = [];
        lines.push('✅ 登录成功');
        lines.push('');
        lines.push('👤 用户：' + name);
        if (u.email) lines.push('📧 邮箱：' + u.email);
        lines.push('🏅 等级：Lv' + level + ' · ' + groupName + (isMember ? '（会员）' : '（普通）'));
        if (expires) lines.push('⏰ 会员到期：' + expires);
        if (masked) lines.push('🔑 Token：' + masked);
        if (u.last_login_at) lines.push('🕒 上次登录：' + u.last_login_at);
        if (rateWin && rateMax) lines.push('🚦 限流：' + rateWin + '秒内最多 ' + rateMax + ' 次');
        if (devLimit) lines.push('📱 设备上限：' + devLimit + ' 台');
        if (resetLimit && resetDays) lines.push('🔄 Token重置：每 ' + resetDays + ' 天 ' + resetLimit + ' 次');
        if (benefits) {
            lines.push('');
            lines.push('💡 ' + benefits);
        }

        java.longToast('\n' + lines.join('\n'));
    } catch (e) {
        java.toast('\n❌ 登录失败：' + e);
    }
}

function logout() {
    try { source.removeLoginHeader(); } catch (e) {}
    try { source.removeLoginInfo(); } catch (e) {}
    java.toast('已退出登录');
}

function fq_login() {
    try {
        java.startBrowserAwait("https://fanqienovel.com/main/writer/login", "登录");
    } catch (e) {
        java.toast(e);
        return false;
    }

    try {
        cookie.removeCookie("snssdk.com");
    } catch (e) {}

    let sessionId = getSessionIdFromCookie.call(this);
    if (!sessionId) sessionId = getSessionId.call(this);

    if (!sessionId || String(sessionId).trim() == "") {
        java.toast("未获取到登录凭据，登录失败");
        return false;
    }

    let user = "";
    try {
        let resp = java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
            method: "GET",
            headers: { "Cookie": "sessionid=" + sessionId }
        }));
        user = JSON.parse(resp)?.data?.name || "";
    } catch (e) {
        java.log(e);
    }

    if (!user) {
        java.toast("登录凭据无效或已过期，登录失败");
        return false;
    }

    setConfig.call(this, { fanqie_sessionid: sessionId });

    java.toast("\n\n欢迎 " + user + "\n登录成功！");
    return true;
}

function fq_logout() {
    try { cookie.removeCookie("fanqienovel.com"); } catch (e) {}
    try { cookie.removeCookie("snssdk.com"); } catch (e) {}
    setConfig.call(this, { fanqie_sessionid: "" });
    java.toast('已退出番茄登录');
}

