function switchServer() {
    let list = getHosts();
    if (!list.length) { java.toast('未配置服务器'); return; }
    let cur = getHost.call(this);
    let idx = list.indexOf(cur);
    let next = list[(idx + 1) % list.length];
    setConfig.call(this, { host: next });
    java.toast('已切换服务器：\n' + next);
}

function checkServer() {
    let cur = getHost.call(this);
    java.toast('正在检测：\n' + cur);
    let t1 = Date.now();
    try {
        let opt = { headers: buildHeaders.call(this) };
        let res = java.ajax(cur + '/api/site/public,' + JSON.stringify(opt));
        let ms = Date.now() - t1;
        let obj = null;
        try { obj = JSON.parse(res); } catch (e) { obj = null; }
        let siteName = (obj.data && obj.data.site_name) ? String(obj.data.site_name) : '未知';
        let ok = !!(obj.code == 0 && siteName.indexOf('听雪') >= 0);
        let elapsed = (obj.meta && obj.meta.elapsedMs != null) ? obj.meta.elapsedMs : ms;
        let level = elapsed < 800 ? '💖 优秀' : elapsed < 2000 ? '💛 一般' : '💔 较慢';
        java.longToast(
            '服务器：' + cur + '\n' +
            '站点：' + siteName + (ok ? ' ✅' : ' ❌') + '\n' +
            '延迟：' + elapsed + 'ms（' + level + '）'
        );
    } catch (e) {
        java.longToast('服务器：' + cur + '\n❌ 连接失败\n' + e);
    }
}

function toggleRefresh() {
    let conf = getConfig.call(this);
    let on = (conf.chapter_refresh_force || 'off') == 'on';
    setConfig.call(this, { chapter_refresh_force: on ? 'off' : 'on' });
    java.toast(on ? '\n✔️已关闭强制刷新' : '\n❗已开启强制刷新（绕过缓存）');
}

function showConfig() {
    let c = getConfig.call(this);
    let s = c.sources || {};
    let lines = [];
    ['novel','audio','comic','video','download'].forEach(function(t){
        let arr = s[t] || [];
        let label = {novel:'小说',audio:'听书',comic:'漫画',video:'短剧',download:'下载'}[t];
        lines.push(label + '：' + (arr.length ? arr.join('、') : '全部'));
    });
    let msg = '当前配置：\n' +
        '服务器：' + getHost.call(this) + '\n' +
        lines.join('\n') + '\n' +
        '性别：' + (c.gender == 'girl' ? '女频' : '男频') + '\n' +
        '账号：' + (getToken.call(this).b64 ? '已登录' : '未登录') + '\n' +
        '番茄：' + (getSessionId.call(this) ? '已登录' : '未登录');
    java.longToast(msg);
}

