        try {
            let chUrl = String(chapter.url);
            let b64 = chUrl.replace(/^data:contentUrl;base64,/, '');
            let idx = b64.indexOf(',');
            if (idx >= 0) b64 = b64.substring(0, idx);
            let params = JSON.parse(java.base64Decode(b64));
            let bid = params.book_id || '';
            let cid = params.item_id || '';
            let src = params.source || '';
            if (bid && cid) {
                targetUrl = getHost.call(this) + '/comment?tab=chapter&book_id=' + bid
                          + '&item_id=' + cid
                          + '&source=' + src;
            }
        } catch (e) {}
    }

    // 详情页：书评
    if (!targetUrl && book && book.tocUrl) {
        try {
            let tocUrl = String(book.tocUrl);
            let b64 = tocUrl.replace(/^data:catalogUrl;base64,/, '');
            let idx = b64.indexOf(',');
            if (idx >= 0) b64 = b64.substring(0, idx);
            let catalog = JSON.parse(java.base64Decode(b64));
            let bid = catalog.book_id || catalog.bookid || '';
            let src = catalog.source || '';
            if (bid) {
                targetUrl = getHost.call(this) + '/comment?tab=book&book_id=' + bid
                          + '&source=' + src;
            }
        } catch (e) {}
    }

