@js:
let chapterParams = JSON.parse(java.hexDecodeToString(result));
chapterParams.version = localVersion;

let conf = getConfig.call(this);
let sourceName = chapterParams.source || '';

if (conf.chapter_refresh_force == 'on') {
    chapterParams.force_refresh = 'on';
}

let toneVar = String(book.getVariable('custom') || '');
if (!toneVar) {
    if (sourceName == '番茄听书') toneVar = '1';
    else if (sourceName == '书旗听书') toneVar = 'yifei';
}
chapterParams.tone_id = toneVar;
syncProgress.call(this, chapterParams);

let paraOn = (conf.para_review || 'off') == 'on';
let paraStyle = conf.para_style || 'TEXT';
let syOn = (conf.para_sy || 'off') == 'on';

if (syOn) {
    chapterParams.devicetype = "ios";
} else {
    chapterParams.devicetype = "android";
}

let paraSources = ['番茄小说', '企鹅阅读', '晋江', '七猫', '少年梦', '书旗'];
if (paraOn && paraSources.indexOf(sourceName) !== -1) {
    chapterParams.review = 'on';
    chapterParams.style = paraStyle;
}

if (sourceName == '书旗听书' || sourceName == '番茄听书') {
    let obj = postJson.call(this, '/api/audio', chapterParams);
    let data = obj.data || {};
    result = data.main_url || '';
} else {
    let obj = postJson.call(this, '/api/content', chapterParams);

    if (shouldBlockByVersion.call(this, obj.data && obj.data.version)) {
        result = '';
    } else {
        let content = (obj.data && obj.data.content != null) ? obj.data.content : obj.message;
        let tab = (obj.data && obj.data.tab) || chapterParams.tab || '';

        if (tab == 'video' && content && /^https?:\/\//i.test(String(content))) {
            if (book.durChapterIndex == chapter.index) {
                try {
                    java.startBrowser(String(content), chapter.title);
                    java.toast('正在加载视频\n视频加载较慢，请耐心等待');
                } catch (e) {}
            }
            result = '【刷新正文】播放\n直链:\n' + content;
        } else {
            result = content;
        }
    }
}

