    else if (sourceName == '书旗听书') toneVar = 'yifei';
}
chapterParams.tone_id = toneVar;

let allowSources = ['番茄听书', '番茄畅听', '七猫听书', '酷我听书', '书旗听书'];
if (allowSources.indexOf(sourceName) == -1) {
    result = '';
} else {
    let headers = buildHeaders.call(this);
    headers['Content-Type'] = 'application/json';
    let op = { method: "POST", body: JSON.stringify(chapterParams), headers: headers };
    let url = getHost.call(this) + `/api/lrc,${JSON.stringify(op)}`;
    let res = java.ajax(url);
    res = decryptIfEncrypted.call(this, res);
    let obj = JSON.parse(res);
    result = (obj.data && obj.data.lrc) ? obj.data.lrc : '';
}

